parameters.jsCode:
const data = $input.first().json.body || $input.first().json;

// Determine confidence color
const confidenceScore = parseFloat(data.confidence_score);
let confidenceColor = '28a745'; // Green
if (confidenceScore < 60) {
  confidenceColor = 'dc3545'; // Red
} else if (confidenceScore < 75) {
  confidenceColor = 'ffc107'; // Yellow
}

return {
  json: {
    report_id: data.report_id || '',
    company_name: data.company_name || '',
    confidence_score: data.confidence_score || '',
    strategic_question: data.strategic_question || '',
    google_doc_url: data.google_doc_url || '',
    user_email: data.user_email || '',
    teams_webhook_url: data.teams_webhook_url || process.env.TEAMS_WEBHOOK_URL,
    confidence_color: confidenceColor,
    timestamp: new Date().toISOString(),
    executive_summary: data.executive_summary || '',
    top_recommendation: data.top_recommendation || ''
  }
};

